SET status = #{status},
    approved_at = #{now},
    approved_by = #{approvedBy},
    updated_at = #{now}
WHERE id = #{id}

UPDATE user_account
SET avatar_key = #{storageKey},
    avatar_content_type = #{contentType},
    avatar_updated_at = #{now},
    updated_at = #{now}
WHERE id = #{id}

UPDATE user_account
SET last_login_at = #{now},
    updated_at = #{now}
WHERE id = #{id}
